enum RecallSchemaV1: VersionedSchema {
    static var versionIdentifier: Schema.Version = .init(1, 0, 0)
    static var models: [any PersistentModel.Type] = [Deck.self, Card.self, ReviewLog.self]
}

enum RecallMigrationPlan: SchemaMigrationPlan {
    static let schemas: [any VersionedSchema.Type] = [RecallSchemaV1.self]
    static let stages: [MigrationStage] = []
}

public enum ModelContainerFactory {
    public static func makeContainer() -> Result<ModelContainer, RecallDataError> {
        do {
            // ModelContainer's `for:` parameter takes a `Schema`, not a
            // `VersionedSchema.Type` directly — `Schema(versionedSchema:)` is
            // the documented bridge (see Apple's "Migrate to SwiftData" sample).
            // The original direct-type-argument form here would not type-check.
            let schema = Schema(versionedSchema: RecallSchemaV1.self)
            let container = try ModelContainer(
                for: schema,
                migrationPlan: RecallMigrationPlan.self
            )
            return .success(container)
        } catch {
            return .failure(.containerUnavailable(underlying: error.localizedDescription))
        }
    }
}

