/// Top of the view hierarchy. Switches on AppRootState so a failed store open
/// renders RecoveryView instead of crashing ([REDACTED:high_entropy]).
struct RootContainerView: View {
    let state: AppRootState
    let onRetry: () -> Void

    var body: some View {
        switch state {
        case .loading:
            LoadingStateView(message: "Opening Recall…", testId: "appRoot.loading")
                .accessibilityIdentifier("appRoot.loading")
        case .ready(let container):
            AppShellView()
                .modelContainer(container)
        case .recoveryNeeded(let error):
            RecoveryView(error: error, onRetry: onRetry)
        }
    }
}

